import torch
import torch.nn.functional as F
import pytorch_msssim
import torch.nn as nn

def tv_loss(x):
    dx = torch.abs(x[:, :, :, :-1] - x[:, :, :, 1:])
    dy = torch.abs(x[:, :, :-1, :] - x[:, :, 1:, :])
    return torch.mean(dx) + torch.mean(dy)

def multiplicative_cycle_loss(noisy, denoised, eps=1e-6):
    ratio = (noisy + eps) / (denoised + eps)
    recon = denoised * ratio.clamp(min=0.5, max=2.0)
    return torch.mean((torch.log(noisy + eps) - torch.log(recon + eps))**2)

def structure_consistency_loss(noisy, denoised):
    return 1 - pytorch_msssim.ssim(denoised, noisy, data_range=1.0)

def frequency_consistency_loss(noisy, denoised):
    f_noisy = torch.fft.rfft2(noisy)
    f_denoised = torch.fft.rfft2(denoised)
    mag_noisy = torch.abs(f_noisy)
    mag_denoised = torch.abs(f_denoised)
    return F.l1_loss(mag_noisy, mag_denoised)

def speckle_stat_loss(noisy, denoised, eps=1e-6):
    """散斑统计一致性 (乘性噪声) — 对数域KL散度"""
    log_noisy = torch.log(noisy + eps)
    log_denoised = torch.log(denoised + eps)
    mu_n, sigma_n = log_noisy.mean(), log_noisy.std()
    mu_d, sigma_d = log_denoised.mean(), log_denoised.std()

    kl = torch.log(sigma_d / sigma_n + eps) + (sigma_n**2 + (mu_n - mu_d)**2) / (2 * sigma_d**2) - 0.5
    return kl

def texture_consistency_loss(noisy, denoised, patch=5, eps=1e-6):
    """局部方差一致性：保证纹理粗细不被平滑掉"""
    kernel = torch.ones(1, 1, patch, patch, device=noisy.device) / (patch * patch)
    mean_noisy = F.conv2d(noisy, kernel, padding=patch//2)
    mean_denoised = F.conv2d(denoised, kernel, padding=patch//2)

    var_noisy = F.conv2d(noisy**2, kernel, padding=patch//2) - mean_noisy**2
    var_denoised = F.conv2d(denoised**2, kernel, padding=patch//2) - mean_denoised**2

    return F.l1_loss(var_denoised, var_noisy)

